  "anomalies": [
    {
      "category": "bridged_nets",
      "components": ["U2", "J1", "J8", "R1", "R2", "R21"],
      "pins": ["U2.1", "J1.16", "J8.16", "R1.2", "R2.1", "R21.1"],
      "nets": ["/NET0019", "/NET0012", "/NET0035", "Net-(J10-Pin_3)"],
      "observed": "Net /NET0019 contains U2 pin 1 (RO) and J1/J8 pin 16, which are the RXD2/PortC UART net, but the same net is also connected through R1 (1 kΩ) to the servo signal pin J10 pin 3 and through 0 Ω jumpers R2 and R21 to M5Stack bus pins 20 and 22.",
      "expected": "The RXD2/MAX3485 RO net should remain separate from the PWM GPIO/servo signal path. In PWM mode, the servo signal pin should be driven from the selected PWM GPIO net only, while PortC UART pins should be unused; the spec explicitly says PWM mode leaves PortC completely unused.",
      "evidence": [
        {
          "source": "netlist",
          "quote": "(net (code \"19\") (name \"/NET0019\") (node (ref \"J1\") (pin \"16\")) (node (ref \"J8\") (pin \"16\")) (node (ref \"R2\") (pin \"1\")) (node (ref \"R1\") (pin \"2\")) (node (ref \"R21\") (pin \"1\")) (node (ref \"U2\") (pin \"1\") (pinfunction \"RO\")))"
        },
        {
          "source": "netlist",
          "quote": "(net (code \"35\") (name \"Net-(J10-Pin_3)\") (node (ref \"J10\") (pin \"3\")) (node (ref \"R1\") (pin \"1\")) (node (ref \"R17\") (pin \"2\")) (node (ref \"R7\") (pin \"1\")))"
        },
        {
          "source": "spec",
          "quote": "PortC (the UART pins feeding U1) is left completely unused, matching the README's claim that PWM mode frees PortC for the user."
        }
      ],
      "impact": "UART RXD2 and the MAX3485 receiver output are shorted to the PWM/servo signal path and to bus pins 20/22. This defeats the intended separation of PortC from the PWM channels and can cause bus contention, incorrect servo/serial behavior, or damage if those GPIOs are driven.",
      "confidence": 0.78
    }
  ],
  "summary": "An anomaly is present: the netlist merges the RXD2/MAX3485 RO net with the PWM servo signal path and selected bus pins, contrary to the specification's requirement that PortC remain separate and unused in PWM mode."
}

